57395cc8-6d1f-41f7-bd12-a8212e82aaeb	e9748c33-b368-44fa-892c-7bd434d1d74b	d98cd8e1-8530-4fa8-8121-ccd249905f83	Near Miss	aa1934f5-dfe8-46ec-b661-66f02e7c17c6	\N	b0a46f9f-cf19-4156-a8e8-413360b46e61	2026-05-02 00:00:00	62649b54-469f-4584-9540-48b024edceab	307a539b-2597-4460-978c-05db14c38381	PT41	E449 - NATIANE LOPES R. FRANÇA	t		Porta da mesa 1 com defeito, atingiu meu rosto.	análise da ocorrência	DRAFT	\N	\N	\N	f5534b01-d1b1-4cb5-98bf-6e7a1c67108f	2026-05-02 11:19:29.311	2026-05-13 13:11:44.787	{"fiveWhys": [{"id": "why-1-ea45e3c6-3dab-43c0-b502-7bdbee748a4e", "why": "o que aconteceu?", "answer": "Trabalhadora embateu com cabeça na porta albany, por não estar a contar que porta descesse;\\n\\n"}, {"id": "why-2-4510ce07-e576-468b-b136-dcaebb07f7a7", "why": "Porque a porta desceu sem que a trabalhadora estivesse à espera?", "answer": " A trabalhadora já tinha dado várias ordens de arranque e a porta não fechaba/ a máquina não arrancava;\\n"}, {"id": "why-3-d2087853-0c4a-4881-b261-c55aa8b68bbc", "why": " Porque a porta não desceu quando foi dada ordem, e apenas mais tarde desceu?\\n", "answer": "Foi detetada modo de obstrução no sensor de segurança da porta, sem ninguem ter invadido a área e por isso a porta não desceu. Depois o modo obstrução \\"desapareceu\\" e a porta avançou sem ser dado nova ordem de arranque.\\n"}, {"id": "why-4-4a2f91c5-7d21-4d79-a7e6-39fae023b224", "why": "Porque o sensor passou para \\"modo de obstrução\\"?", "answer": " Sensor desposicionou-se ao longo da guia de posicionamento;"}, {"id": "why-5-4c2b12c5-f3c9-4ac3-9ca4-aeaf49306276", "why": "Como desapareceu o modo obstrução e a máquina avançou?\\n", "answer": "Alegadamente a vibração da máquina fez o sensor voltar à posição padrão\\n"}, {"id": "why-6-b38c0f68-96cf-4ca2-932e-2d8195222bd7", "why": "Porque a porta fechou sem ser dada ordem após reposição do sensor? \\n", "answer": " Porque a programação da porta não preve que seja necessário dar ordem de start de ciclo para fechar porta, após a reposição de todos os fatores;"}], "natureId": "307a539b-2597-4460-978c-05db14c38381", "whereText": "PT41", "bodyPartId": "025fe1ea-81a1-4aa3-99a8-18c586dfa5ce", "analysisText": "1. Trabalhadora montou os componentes na mesa, saiu da zona de montagem e carregou no botão de start ciclo;\\n2. A porta albany não desceu. Trabalhadora deu nova orde de arranque de ciclo e porta continou a não descer a porta;\\n3. A trabalhadora dirigiu-se ao interior da zona de montagem para verificar se os componentes estavam mal montados e nesse momento a porta desceu. \\n4. Quando a porta desceu a trabalhadora no movimento de caminhar, atingiu a porta com a cabeça.\\n", "workstationId": "a83cf868-743e-47b9-b116-1a02722f61a8", "sifPsifDecision": {"result": "NO_PSIF", "actualSif": "NO", "exposures": {"workAtHeight": "NO", "confinedSpace": "", "suspendedLoad": "NO", "energyIsolation": "NO", "mobileEquipment": "NO", "movingEquipment": "YES", "significantMassEnergy": ""}, "oneWhatIfAway": "NO", "noPsifExplanation": "", "repeatedSifPotential": "NO"}, "involvedWorkerId": "9b3c31d8-5c36-4d4b-a2ee-97e492e6e645", "previousDetected": "NO", "rootCauseDetails": [{"id": "1-2-limited-experience-with-the-specific-task", "label": "1.2 Limited experience with the specific task", "comment": "Trabalhadora com pouca experiência no posto de trabalho, no entanto este não foi um fator que levou ao incidente.", "isRootCause": false}, {"id": "6-2-lack-of-maintenance", "label": "6.2 Lack of maintenance", "comment": "As portas albany dispõe de um plano de manutenção que não está contemplado na manutenção preventiva. A manutenção ia prevenir a saída de posição do sensor de segurança, mas não resolve a questão da programação", "isRootCause": false}, {"id": "6-4-anomalous-functioning-of-equipment-facilities", "label": "6.4 Anomalous functioning of equipment / facilities", "comment": "A programação da porta albany não preve que seja necessário uma nova ação de \\"start ciclo\\" após a reposição dos fatores.", "isRootCause": true}], "involvedWorkerName": "NATIANE LOPES R. FRANÇA", "involvedWorkerDepartment": null, "involvedWorkerEmployeeNo": "E449", "previousDetectedDescription": ""}	f
a3d52c54-1df8-4603-8a8e-bf26707028de	e9748c33-b368-44fa-892c-7bd434d1d74b	d70f79d3-9675-4dd0-ad30-d5aa4b16c472	Near Miss	c7424501-295a-40af-85be-efb34563236d	\N	\N	2026-05-13 00:00:00	62649b54-469f-4584-9540-48b024edceab	Near Miss	PT17	107 - SÓNIA ALEXANDRA PEREIRA GONÇALVES	t	Lifting operations	Caixa de suporte amortecedor onde estavam  a colocar o produto final estava fora dos limites da palete. Ao colocar a nova palete vazia, tocou na caixa e essa caixa caiu.	teste	IN_APPROVAL	\N	\N	\N	f5534b01-d1b1-4cb5-98bf-6e7a1c67108f	2026-05-13 14:57:22.889	2026-05-14 21:34:47.695	{"fiveWhys": [{"id": "why-1-f797727f-f149-40f5-85f3-8b4e7735c1d5", "why": "Why did the box fall on the floor?", "answer": "Because the forklift hit the box"}, {"id": "why-2-6bf09cef-394d-49d6-a627-bbd8b9935318", "why": "Why the forklift hit the box?", "answer": "Because the box was outside the boundaries of the pallet already on the platform"}, {"id": "why-3-2d5ce51a-d9db-49bc-ad4c-ac4e1aea3224", "why": "Why the box was outside the limits?", "answer": "Because the pallet has damaged edge boards"}, {"id": "why-4-42ea4b2c-c887-45e1-bf18-525ad82e518b", "why": "Why are the edges of the pallets damaged?", "answer": "Because the pallet was NOK and wasn't rejected"}, {"id": "why-5-d52eb947-9adf-40b3-ab5c-d3167cd7cf13", "why": "Why wasn’t the pallet rejected?", "answer": "because the production team is not aware of the criteria required to reject a pallet"}], "natureId": "", "whereText": "PT17", "bodyPartId": "", "actionPlans": [{"id": "ec0250c3-8bb8-41d4-8bf2-eacbdea2bed5", "title": "", "dueDate": "", "category": "CORRECTIVE", "priority": "MEDIUM", "description": "", "ownerUserId": ""}], "analysisText": "Caixa de suporte amortecedor onde estavam  a colocar o produto final estava fora dos limites da palete. Ao colocar a nova palete vazia, tocou na caixa e essa caixa caiu. ", "workstationId": "13536ce5-156d-4e6d-a568-e0f2e456457c", "sifPsifDecision": {"result": "PSIF", "actualSif": "NO", "exposures": {"workAtHeight": "", "confinedSpace": "", "suspendedLoad": "NO", "energyIsolation": "", "mobileEquipment": "YES", "movingEquipment": "", "significantMassEnergy": ""}, "oneWhatIfAway": "YES", "noPsifExplanation": "", "repeatedSifPotential": "YES"}, "involvedWorkerId": "6f43266a-18d6-48a1-97f0-6166230a3b63", "previousDetected": "YES", "rootCauseDetails": [{"id": "6-3-weakness-in-design", "label": "6.3 Weakness in design", "comment": "Plataforma tem batente para evitar queda de contentores e da palete, no entanto como este batente está faciado com a palete, as caixas podem cair para  o interior da linha. \\n\\nThe platform has a stop to prevent containers and pallets from falling off; however, as this stop is flush with the pallet, the boxes may fall onto the conveyor belt. ", "isRootCause": true}, {"id": "6-4-anomalous-functioning-of-equipment-facilities", "label": "6.4 Anomalous functioning of equipment / facilities", "comment": "Palete danificada, não apresentando limitadores. \\n\\nDamaged pallet, with no stop blocks. ", "isRootCause": true}, {"id": "2-1-lack-of-concentration", "label": "2.1 Lack of concentration", "comment": "Os trabalhadores colocaram a caixa na palete e a mesma movimentou-se sem se terem apercebido que a caixa estava fora dos limites da plataforma.\\nThe workers placed the box on the pallet, and it moved without them realising that the box was outside the platform’s boundaries.", "isRootCause": false}], "involvedWorkerName": "SÓNIA ALEXANDRA PEREIRA GONÇALVES", "involvedWorkerDepartment": null, "involvedWorkerEmployeeNo": "107", "previousDetectedDescription": ""}	f
