99a5e629-72f3-45bd-873c-ff2347d0b158	SEWO	57395cc8-6d1f-41f7-bd12-a8212e82aaeb	UPDATE	{"after": {"id": "57395cc8-6d1f-41f7-bd12-a8212e82aaeb", "areaId": "aa1934f5-dfe8-46ec-b661-66f02e7c17c6", "lineId": null, "status": "DRAFT", "howText": "Porta da mesa 1 com defeito, atingiu meu rosto.", "plantId": "e9748c33-b368-44fa-892c-7bd434d1d74b", "shiftId": "b0a46f9f-cf19-4156-a8e8-413360b46e61", "whoText": "E449 - NATIANE LOPES R. FRANÇA", "whatText": "307a539b-2597-4460-978c-05db14c38381", "createdAt": "2026-05-02T11:19:29.311Z", "updatedAt": "2026-05-13T13:11:44.787Z", "whereText": "PT41", "whichText": "", "approvedAt": null, "attachments": [{"id": "2b6dcd1c-492e-4c39-abdd-460ec6d309f2", "type": "EVENT_EVIDENCE", "sewoId": "57395cc8-6d1f-41f7-bd12-a8212e82aaeb", "fileKey": "maap/sewo/243b5dbe-527b-463e-8a4a-7b575d45d93a.jpeg", "fileName": "WhatsApp Image 2026-02-23 at 21.20.11.jpeg", "createdAt": "2026-05-02T11:19:29.311Z", "contentType": "image/jpeg", "uploadedById": "62649b54-469f-4584-9540-48b024edceab"}], "analysisDate": "2026-05-02T00:00:00.000Z", "templateData": {"fiveWhys": [{"id": "why-1-ea45e3c6-3dab-43c0-b502-7bdbee748a4e", "why": "o que aconteceu?", "answer": "Trabalhadora embateu com cabeça na porta albany, por não estar a contar que porta descesse;\\n\\n"}, {"id": "why-2-4510ce07-e576-468b-b136-dcaebb07f7a7", "why": "Porque a porta desceu sem que a trabalhadora estivesse à espera?", "answer": " A trabalhadora já tinha dado várias ordens de arranque e a porta não fechaba/ a máquina não arrancava;\\n"}, {"id": "why-3-d2087853-0c4a-4881-b261-c55aa8b68bbc", "why": " Porque a porta não desceu quando foi dada ordem, e apenas mais tarde desceu?\\n", "answer": "Foi detetada modo de obstrução no sensor de segurança da porta, sem ninguem ter invadido a área e por isso a porta não desceu. Depois o modo obstrução \\"desapareceu\\" e a porta avançou sem ser dado nova ordem de arranque.\\n"}, {"id": "why-4-4a2f91c5-7d21-4d79-a7e6-39fae023b224", "why": "Porque o sensor passou para \\"modo de obstrução\\"?", "answer": " Sensor desposicionou-se ao longo da guia de posicionamento;"}, {"id": "why-5-4c2b12c5-f3c9-4ac3-9ca4-aeaf49306276", "why": "Como desapareceu o modo obstrução e a máquina avançou?\\n", "answer": "Alegadamente a vibração da máquina fez o sensor voltar à posição padrão\\n"}, {"id": "why-6-b38c0f68-96cf-4ca2-932e-2d8195222bd7", "why": "Porque a porta fechou sem ser dada ordem após reposição do sensor? \\n", "answer": " Porque a programação da porta não preve que seja necessário dar ordem de start de ciclo para fechar porta, após a reposição de todos os fatores;"}], "natureId": "307a539b-2597-4460-978c-05db14c38381", "whereText": "PT41", "bodyPartId": "025fe1ea-81a1-4aa3-99a8-18c586dfa5ce", "analysisText": "1. Trabalhadora montou os componentes na mesa, saiu da zona de montagem e carregou no botão de start ciclo;\\n2. A porta albany não desceu. Trabalhadora deu nova orde de arranque de ciclo e porta continou a não descer a porta;\\n3. A trabalhadora dirigiu-se ao interior da zona de montagem para verificar se os componentes estavam mal montados e nesse momento a porta desceu. \\n4. Quando a porta desceu a trabalhadora no movimento de caminhar, atingiu a porta com a cabeça.\\n", "workstationId": "a83cf868-743e-47b9-b116-1a02722f61a8", "sifPsifDecision": {"result": "NO_PSIF", "actualSif": "NO", "exposures": {"workAtHeight": "NO", "confinedSpace": "", "suspendedLoad": "NO", "energyIsolation": "NO", "mobileEquipment": "NO", "movingEquipment": "YES", "significantMassEnergy": ""}, "oneWhatIfAway": "NO", "noPsifExplanation": "", "repeatedSifPotential": "NO"}, "involvedWorkerId": "9b3c31d8-5c36-4d4b-a2ee-97e492e6e645", "previousDetected": "NO", "rootCauseDetails": [{"id": "1-2-limited-experience-with-the-specific-task", "label": "1.2 Limited experience with the specific task", "comment": "Trabalhadora com pouca experiência no posto de trabalho, no entanto este não foi um fator que levou ao incidente.", "isRootCause": false}, {"id": "6-2-lack-of-maintenance", "label": "6.2 Lack of maintenance", "comment": "As portas albany dispõe de um plano de manutenção que não está contemplado na manutenção preventiva. A manutenção ia prevenir a saída de posição do sensor de segurança, mas não resolve a questão da programação", "isRootCause": false}, {"id": "6-4-anomalous-functioning-of-equipment-facilities", "label": "6.4 Anomalous functioning of equipment / facilities", "comment": "A programação da porta albany não preve que seja necessário uma nova ação de \\"start ciclo\\" após a reposição dos fatores.", "isRootCause": true}], "involvedWorkerName": "NATIANE LOPES R. FRANÇA", "involvedWorkerDepartment": null, "involvedWorkerEmployeeNo": "E449", "previousDetectedDescription": ""}, "isAutoCreated": false, "usualWorkYesNo": true, "approvalComment": null, "causeSelections": [], "communicationId": "d98cd8e1-8530-4fa8-8121-ccd249905f83", "approvedByUserId": null, "performedByUserId": "62649b54-469f-4584-9540-48b024edceab", "eventClassification": "Near Miss", "causeCatalogVersionId": "f5534b01-d1b1-4cb5-98bf-6e7a1c67108f", "immediateCorrectiveActionText": "análise da ocorrência"}, "before": {"id": "57395cc8-6d1f-41f7-bd12-a8212e82aaeb", "areaId": "aa1934f5-dfe8-46ec-b661-66f02e7c17c6", "lineId": null, "status": "DRAFT", "howText": "Porta da mesa 1 com defeito, atingiu meu rosto.", "plantId": "e9748c33-b368-44fa-892c-7bd434d1d74b", "shiftId": "b0a46f9f-cf19-4156-a8e8-413360b46e61", "whoText": "E449 - NATIANE LOPES R. FRANÇA", "whatText": "307a539b-2597-4460-978c-05db14c38381", "createdAt": "2026-05-02T11:19:29.311Z", "updatedAt": "2026-05-13T13:03:24.659Z", "whereText": "PT41", "whichText": "", "approvedAt": null, "attachments": [{"id": "2b6dcd1c-492e-4c39-abdd-460ec6d309f2", "type": "EVENT_EVIDENCE", "sewoId": "57395cc8-6d1f-41f7-bd12-a8212e82aaeb", "fileKey": "maap/sewo/243b5dbe-527b-463e-8a4a-7b575d45d93a.jpeg", "fileName": "WhatsApp Image 2026-02-23 at 21.20.11.jpeg", "createdAt": "2026-05-02T11:19:29.311Z",