70554261-a821-46f4-a890-0f646bdaac46	SEWO	a3d52c54-1df8-4603-8a8e-bf26707028de	CREATE	{"after": {"id": "a3d52c54-1df8-4603-8a8e-bf26707028de", "areaId": "c7424501-295a-40af-85be-efb34563236d", "lineId": null, "status": "DRAFT", "howText": "Caixa de suporte amortecedor onde estavam  a colocar o produto final estava fora dos limites da palete. Ao colocar a nova palete vazia, tocou na caixa e essa caixa caiu. ", "plantId": "e9748c33-b368-44fa-892c-7bd434d1d74b", "shiftId": null, "whoText": "107 - SÓNIA ALEXANDRA PEREIRA GONÇALVES", "whatText": "Near Miss", "createdAt": "2026-05-13T14:57:22.889Z", "updatedAt": "2026-05-13T14:57:22.889Z", "whereText": "PT17", "whichText": "Lifting operations", "approvedAt": null, "attachments": [{"id": "861ffbd9-b0a6-4088-83ae-d1a9d413ccca", "type": "EVENT_EVIDENCE", "sewoId": "a3d52c54-1df8-4603-8a8e-bf26707028de", "fileKey": "maap/sewo/375517ee-fb73-4679-8757-16133837e340.jpeg", "fileName": "WhatsApp Image 2026-04-10 at 09.34.54.jpeg", "createdAt": "2026-05-13T14:57:22.889Z", "contentType": "image/jpeg", "uploadedById": "62649b54-469f-4584-9540-48b024edceab"}], "analysisDate": "2026-05-13T00:00:00.000Z", "templateData": {"fiveWhys": [{"id": "why-1-f797727f-f149-40f5-85f3-8b4e7735c1d5", "why": "Why did the box fall on the floor?", "answer": "Because the forklift hit the box"}, {"id": "why-2-6bf09cef-394d-49d6-a627-bbd8b9935318", "why": "Why the forklift hit the box?", "answer": "Because the box was outside the boundaries of the pallet already on the platform"}, {"id": "why-3-2d5ce51a-d9db-49bc-ad4c-ac4e1aea3224", "why": "Why the box was outside the limits?", "answer": "Because the pallet has damaged edge boards"}, {"id": "why-4-42ea4b2c-c887-45e1-bf18-525ad82e518b", "why": "Why are the edges of the pallets damaged?", "answer": "Because the pallet was NOK and wasn't rejected"}, {"id": "why-5-d52eb947-9adf-40b3-ab5c-d3167cd7cf13", "why": "Why wasn’t the pallet rejected?", "answer": "because the production team is not aware of the criteria