90b0d5ea-0055-4eec-a772-dd82980ce4ac	Communication	db802cbb-3811-41df-bda7-08d7c6786e27	CREATE	{"after": {"id": "db802cbb-3811-41df-bda7-08d7c6786e27", "type": "FIRST_AID", "areaId": "355cc635-a73e-4d0b-9c1e-1341d0a1d078", "lineId": null, "source": "TOKEN_REPORT", "status": "SUBMITTED", "isFatal": false, "plantId": "73417706-d65a-4e6e-9c75-d7b26b6042e4", "hasLeave": false, "lostDays": null, "createdAt": "2026-04-21T08:00:28.065Z", "updatedAt": "2026-04-21T08:00:28.065Z", "bodyPartId": "cc5641d5-65fd-46f6-8cf0-c9ad616caed8", "reportedAt": "2026-04-21T08:00:28.065Z", "returnDate": null, "targetText": "HELENA Mª LAMEIRA ALVES COSTA FERREIRA", "attachments": [], "description": "Durante intervenção corretiva no circuito de arrefecimento da Estacionária 03, ocorreu restrição de fluxo em mangueira após reparação inicial, originando aumento de pressão e temperatura no sistema. Verificou-se rutura do tubo com projeção de fluido aquecido/vapor. A operária Helena Ferreira foi atingida na face por fluido aquecido e encaminhada ao posto médico, onde recebeu compressas frias, aplicação de pomada e avaliação dos sinais vitais. A condição técnica foi corrigida e implementadas proteções físicas para mitigação de eventual nova rutura. O equipamento encontra-se em operação normal.", "equipmentId": null, "riskThemeId": "c89fb8ad-4e4c-4e08-acb6-88fa8cae233b", "validatedAt": null, "validatedBy": null, "injuryTypeId": "7015e786-064f-417d-9c82-e4a3107851cc", "isContractor": false, "reporterName": "francis", "eventDatetime": "2026-02-27T10:00:00.000Z", "workstationId": "408c4bf6-f289-471e-bbff-eb7449099fe2", "classification": null, "nearMissTypeId": null, "reporterUserId": null, "initialLostDays": null, "suggestedAction": null, "unsafeActTypeId": null, "validationNotes": null, "manuallyClosedAt": null, "manuallyClosedBy": null, "targetEmployeeId": "58891214-092b-4517-9e88-a7717a5e87ad", "targetEmployeeNo": "117", "manualCloseReason": null, "severityPotential": null, "invalidationReason": nu